import React from 'react';
import { Box, Typography, CircularProgress, Stack } from '@mui/material';

type Props = {
  totalAmount: number;
  paidAmount: number;
};

const InstallmentProgress: React.FC<Props> = ({ totalAmount, paidAmount }) => {
  const percentage = totalAmount > 0 ? (paidAmount / totalAmount) * 100 : 0;
  const remainingAmount = totalAmount - paidAmount;

  return (
    <Box
      sx={{
        p: 3,
        borderRadius: 2,
        boxShadow: 1,
        backgroundColor: '#fff',
        maxWidth: 300,
        textAlign: 'center',
      }}
    >
      <Typography variant="h6" gutterBottom>
        สถานะการผ่อนชำระ
      </Typography>

      <Box position="relative" display="inline-flex" mb={2}>
        <CircularProgress
          variant="determinate"
          value={percentage}
          size={120}
          thickness={5}
          sx={{ color: '#1976d2' }}
        />
        <Box
          top={0}
          left={0}
          bottom={0}
          right={0}
          position="absolute"
          display="flex"
          alignItems="center"
          justifyContent="center"
        >
          <Typography variant="h6" component="div" color="textSecondary">
            {`${Math.round(percentage)}%`}
          </Typography>
        </Box>
      </Box>

      <Stack spacing={1}>
        <Typography variant="body2">ยอดรวม: {totalAmount.toLocaleString()} บาท</Typography>
        <Typography variant="body2">ชำระแล้ว: {paidAmount.toLocaleString()} บาท</Typography>
        <Typography variant="body2">คงเหลือ: {remainingAmount.toLocaleString()} บาท</Typography>
      </Stack>
    </Box>
  );
};

export default InstallmentProgress;
